/* ---------- Onda 4a: Painel de fluxo, Pacientes, Agenda, Coleta domiciliar, Transporte, Recebimento ---------- */

/* ===== Painel de fluxo (aba Home e Dashboard: decisão "painel de fluxo", 28/10) ===== */
VIEWS.fluxo=()=>{const porLetra={};'ACTRDLNIG'.split('').forEach(k=>porLetra[k]=0);AMOSTRAS.forEach(a=>{if(porLetra[a.sit]!==undefined)porLetra[a.sit]++});
 const urg=AMOSTRAS.filter(a=>a.urg&&'ACTR'.includes(a.sit));
 return `${pageHead('Início','Painel de fluxo','Tela grande da área técnica: atualiza sozinha a cada minuto, sem nome de paciente, só protocolo. Dados de exemplo.',`${rulesBtn('Painel de fluxo')}<button class="btn sec" onclick="toast('Modo TV: tela cheia, sem menu, atualização a cada 60 s')" ${tipAttr('Modo TV','Abre o painel em tela cheia para a TV da área técnica.')}>Modo TV</button>`)}
<div class="alert info"><span><b>Atualizado às 08:59.</b> O painel avisa quando passa de 5 minutos sem atualizar. ${info('Os limites de alerta (horas parado, prazo vencendo) são configurações do laboratório.')}</span></div>
<div class="card ill">${ILL.grafico}<h3>Funil do dia por situação ${info('Quantas amostras estão em cada letra agora. Urgentes destacadas.')}</h3><div class="sub">${AMOSTRAS.length} amostras hoje · ${urg.length} urgentes em andamento</div>
<div class="funil">${'ACTRDLNIG'.split('').map(k=>`<div class="et clk" role="button" tabindex="0" onclick="listaDrawer('${LETRAS[k]} (${k})',AMOSTRAS.filter(a=>a.sit==='${k}').map(linhaAmostra),'Amostras nesta situação agora.')" ${tipAttr(LETRAS[k],'Clique para ver a lista das amostras nesta situação.')}><span class="at-letter">${k}</span><b>${porLetra[k]}</b><small>${LETRAS[k]}</small></div>`).join('')}</div></div>
<div class="grid larga">
 <div class="card"><h3>Urgentes com prazo ${info('Prazo = hora de entrega prometida na recepção. Vermelho piscando quando vence em menos de 30 min.')}</h3><div class="sub">Em ordem de prazo</div><div class="stack">${urg.map(a=>`<div class="pos ${a.urg?'urg':''}"><span class="n">${a.sit}</span><span><span class="mono">${a.cod}</span><small class="tl" style="display:block">${a.banc} · ${a.ex.join(', ')}</small></span><span class="badge err pisca">${a.prazo}</span></div>`).join('')}</div></div>
 <div class="card"><h3>Paradas há mais tempo ${info('Amostras que não mudam de situação há mais tempo, por posto. Mais de 2 horas vira alerta.')}</h3><div class="sub">Sem mudança de situação</div><div class="barras">${barra('<span class="mono">14-00004471-02-01</span><small class="tl" style="display:block">Posto 14 · T há 2h08</small>',128,180,'2h08')}${barra('<span class="mono">10-00018262-01-01</span><small class="tl" style="display:block">Central · T há 1h04</small>',64,180,'1h04')}${barra('<span class="mono">12-00002210-01-01</span><small class="tl" style="display:block">Posto 12 · R há 1h19</small>',79,180,'1h19')}${barra('<span class="mono">10-00018250-01-01</span><small class="tl" style="display:block">Central · C há 49 min</small>',49,180,'49 min')}</div></div>
 <div class="card"><h3>Tempos médios ${info('Transporte: da saída do posto à chegada na matriz. Realização: total desde a coleta e só dentro da área técnica.')}</h3><div class="sub">Hoje</div><div class="mini">${miniKpi('Transporte · posto 14 '+info('Tempo médio de hoje entre a saída da remessa no posto 14 e a chegada na matriz. Meta: 60 min.'),'52 min','meta 60')}${miniKpi('Transporte · posto 12 '+info('Tempo médio de hoje entre a saída da remessa no posto 12 e a chegada na matriz. Meta: 60 min.'),'1h14','meta 60','warn')}${miniKpi('Realização total '+info('Tempo médio de hoje entre a coleta e a liberação do laudo, contando transporte, recebimento, análise e conferência.'),'4h20','coleta → laudo liberado')}${miniKpi('Só área técnica '+info('Tempo médio de hoje só dentro da área técnica: do recebimento (R) até a liberação (L).'),'2h05','recebido → liberado','ok')}</div></div>
 <div class="card"><h3>Laudos no prazo ${info('Percentual do dia e do mês, e quantos vencem nas próximas 2 horas.')}</h3><div class="mini">${miniKpi('Hoje '+info('Laudos liberados hoje dentro do prazo prometido na recepção.'),'97%','4 atrasados','ok',`listaDrawer('Laudos atrasados hoje',AMOSTRAS.filter(a=>a.prazo==='ontem'||a.sit==='L'&&a.unid!==10).map(linhaAmostra))`)}${miniKpi('Mês '+info('Mesmo indicador acumulado no mês. Meta do laboratório: 95%.'),'96,2%','meta 95%','ok')}${miniKpi('Vencem em 2 h '+info('Laudos ainda não liberados cujo prazo prometido vence nas próximas 2 horas.'),'7','3 urgentes','warn',`listaDrawer('Vencem em 2 h',AMOSTRAS.filter(a=>'ACTRD'.includes(a.sit)&&/^\\d/.test(a.prazo)).map(linhaAmostra))`)}</div></div>
 <div class="card"><h3>Fila da conferência por Dr. ${info('Resultados aguardando assinatura e a espera do mais antigo.')}</h3><div class="barras">${barra('Dra. Helena',214,260,'214 · mais antigo 1h12')}${barra('Dr. Marcos',38,260,'38 · mais antigo 22 min')}</div></div>
 <div class="card"><h3>Recoletas e rejeições ${info('Do dia, por motivo e por posto. Alimenta o indicador de recoleta por causa do PALC.')}</h3><div class="barras">${barra('Hemólise · posto 14',2,4,'2')}${barra('Volume insuficiente · central',1,4,'1')}${barra('Tubo faltante · posto 14',1,4,'1')}</div></div>
 <div class="card"><h3>Críticos abertos ${info('Valores críticos aguardando confirmação de leitura do médico solicitante.')}</h3><div class="stack"><div class="pos urg"><span class="n">K</span><span><span class="mono">10-00018233-01-02</span><small class="tl" style="display:block">Potássio 6,9 mmol/L</small></span><span class="badge err">12 min</span></div><div class="pos urg"><span class="n">GL</span><span><span class="mono">10-00018190-01-01</span><small class="tl" style="display:block">Glicose 38 mg/dL</small></span><span class="badge err pisca">32 min · ligar</span></div></div></div>
 <div class="card"><h3>Aparelhos ${info('Conectados e resultados da última hora. Agente calado além do tempo vira aviso ao supervisor.')}</h3><div class="stack">${APARELHOS.filter(a=>a.conn).map(a=>`<div class="pos"><span class="n" style="width:auto"><span class="badge ${a.on?'ok':'err'}">${a.on?'on':'off'}</span></span><span>${a.n} <small class="tl">· ${a.hora}</small></span><span class="tl">${a.ultima}</span></div>`).join('')}</div></div>
 <div class="card"><h3>Caixas em transporte ${info('Remessas fechadas nos postos que ainda não chegaram, com hora de saída e previsão.')}</h3><div class="stack"><div class="pos"><span class="n">14</span><span>Remessa 14-0319 <small class="tl">· saiu 07:32 · motorista Edson</small></span><span class="badge ok">previsão 08:25 · chegou</span></div><div class="pos"><span class="n">12</span><span>Remessa 12-0188 <small class="tl">· saiu 08:05 · sem motorista com app</small></span><span class="badge warn">previsão 09:10</span></div></div></div>
</div>
${piada(16,{tecnico:'O funil não é uma crítica: é só a bancada dizendo "ainda estou aqui" em letras garrafais.',dr:'214 na sua fila, Dr. O painel não julga, só conta. (Conta alto.)',gestor:'Posto 12 sem motorista com app: a remessa chega quando chega, e o painel finge que não viu.',todos:'Painel na TV da área técnica: o único programa que ninguém muda de canal.'})}`};
GUIDES.fluxo=['Olhe o funil: cada letra é uma etapa; o número é quantas amostras estão nela agora.','Os cartões de urgência e críticos abrem a tela que resolve; o resto é só para acompanhar.','O painel fica na TV e atualiza sozinho. Se passar de 5 minutos sem atualizar, ele avisa.'];
REGRAS['Painel de fluxo']={aba:'Home e Dashboard',itens:[['RN06','Painel de fluxo: tela grande, autoatualizada, com tempos médios de transporte e realização, urgentes com prazo, funil por letra, amostras paradas, laudos no prazo, fila por Dr., recoletas e rejeições, críticos abertos, aparelhos e caixas em transporte.'],['Perfil','Respeita o perfil de quem olha; nunca mostra nome de paciente, só protocolo.'],['Limites','Horas parado e prazo vencendo são configurações do laboratório.'],['CB03','Mostra a hora da última atualização e avisa quando passa de 5 minutos.']]};

/* ===== Pacientes (aba Atendimento, seções 4.x: cadastro, fusão, importação, exportação, LGPD) ===== */
let PC_Q='',PC_SIT='';
VIEWS.pacientes=()=>`${pageHead('Atendimento','Pacientes','Cadastro único por CPF para a clínica, o laboratório, a imagem e o hospital: uma linha do tempo com consultas, exames, laudos, prescrições e pagamentos. Dados de exemplo.',`${rulesBtn('Pacientes')}<button class="btn sec" onclick="pacImportar()" ${tipAttr('Importar','Importa pacientes do sistema antigo ou de planilha, com de→para e prévia. Exige permissão própria e fica na auditoria.')}>Importar</button><button class="btn sec" onclick="toast('Exportação gerada com CPF mascarado e registrada na auditoria','warn')" ${tipAttr('Exportar','Exporta a lista com CPF mascarado. Exige permissão própria; cada exportação fica na auditoria.')}>Exportar</button><button class="btn" onclick="pacNovo()" ${tipAttr('Novo paciente','Cadastro pelo CPF; sem CPF só com a exceção configurada (criança, estrangeiro).')}>${I.plus} Novo paciente</button>`)}
<div class="filters"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Nome, CPF ou telefone" value="${esc(PC_Q)}" oninput="PC_Q=this.value;$('#pcBody').innerHTML=pcRows()" aria-label="Buscar paciente"></div><select class="in" style="width:auto" onchange="PC_SIT=this.value;$('#pcBody').innerHTML=pcRows()"><option value="">Ativos</option><option value="off">Desativados</option><option value="all">Todos</option></select><button class="chip" onclick="pacFundir()" ${tipAttr('Fundir duplicados','Junta dois cadastros da mesma pessoa, mantendo todo o histórico. Exige permissão própria.')}>Fundir duplicados</button></div>
<div class="tablewrap"><table class="at-table"><thead><tr><th>Paciente</th><th>CPF</th><th>Telefone</th><th>Último atendimento</th><th>Situação</th><th></th></tr></thead><tbody id="pcBody">${pcRows()}</tbody></table></div>
${piada(17,{recepcao:'Cadastro com CPF certo é meio atendimento. A outra metade é o paciente lembrar o nome da mãe.',todos:'Paciente duplicado é como meia sem par: todo mundo tem, ninguém assume.'})}`;
function pcRows(){const q=semAc(PC_Q.trim()),qd=soDig(PC_Q);const r=PACIENTES.filter(p=>(PC_SIT==='all'||(PC_SIT==='off'?!p.ativo:p.ativo))&&(q.length<2||semAc(p.n).includes(q)||(qd.length>=3&&(soDig(p.cpf).includes(qd)||soDig(p.tel).includes(qd)))));
 if(!r.length)return vazioLinha(6,'Ninguém encontrado','Confira o nome ou o CPF, ou cadastre um novo paciente.');
 const ult={'123.456.789-09':'27/10 (orçamento)','987.654.321-00':'14/10','111.444.777-35':'hoje · 10-00018233','222.333.444-05':'hoje · 10-00018260','555.666.777-80':'28/09 (orçamento)','444.555.666-11':'2024'};
 return r.map(p=>`<tr style="cursor:pointer" onclick="pacFicha('${p.cpf}')" ${tipAttr('Ficha','Abre a ficha com dados, exames, comunicações e rastreabilidade.')}>${td('Paciente',`<div class="two">${esc(p.n)}<small>${dmy(p.dn)} · ${idade(p.dn)} anos${p.resp?' · resp.: '+esc(p.resp.split(' (')[0]):''}</small></div>`)}${td('CPF',`<span class="mono">${cpfMask(p.cpf)}</span>`)}${td('Telefone',esc(p.tel))}${td('Último atendimento',clUltimo(p)||ult[p.cpf]||'—')}${td('Situação',`<span class="badge ${p.ativo?'ok':'neutral'}">${p.ativo?'Ativo':'Desativado'}</span>`)}${td('',p.ativo?`<button class="btn sm sec" onclick="event.stopPropagation();naNovo('atendimento','${p.cpf}',false,true)">Novo atendimento</button>`:`<button class="btn sm neutral" onclick="event.stopPropagation();toast('Só o gestor reativa um paciente desativado','warn')">Reativar</button>`)}</tr>`).join('')}
let PC_ABA='dados';
function pacFicha(cpf,aba){const p=PACIENTES.find(x=>x.cpf===cpf);if(!p)return;PC_ABA=aba||'tempo';const ats=ATENDS.filter(a=>a.n===p.n);
 const abas=[['tempo','Linha do tempo'],['dados','Dados'],['exames','Exames'],['com','Comunicações'],['rastro','Rastreabilidade']];
 const corpo=PC_ABA==='tempo'?clLinhaHtml(p):PC_ABA==='dados'?kvs([['Nome',esc(p.n)],['CPF',`<span class="mono">${cpfMask(p.cpf)}</span> ${info('CPF mascarado na tela; o completo só para quem tem a permissão.')}`],['Nascimento',dmy(p.dn)+' · '+idade(p.dn)+' anos'],['Sexo',p.sx==='F'?'Feminino':'Masculino'],['Mãe',esc(p.mae)],['Telefone',esc(p.tel)],['E-mail',p.email||'—'],p.resp?['Responsável',esc(p.resp)]:null,['Canais autorizados','WhatsApp, e-mail'],['Crônicas',`${p.cron[0]} · ${p.cron[1]} ${info('Respostas crônicas do questionário: ficam no prontuário e voltam preenchidas no próximo atendimento. Só quem tem a permissão vê.')}`],['Faltas na agenda','0']])
 :PC_ABA==='exames'?(ats.length?`<div class="at-list">${ats.map(a=>`<div class="at-row"><div class="grow"><span class="mono">${a.p}</span><small>${a.orig} · ${LETRAS[a.sit]} · ${a.tot}</small></div><button class="btn sm ghost" onclick="toast('Laudo evolutivo: entra na tela de Laudos')">Laudos</button></div>`).join('')}</div>`:'<p style="color:var(--fg2);font-size:14px">Nenhum atendimento deste paciente.</p>')
 :PC_ABA==='com'?`<div class="at-list"><div class="at-row"><div class="grow">Lembrete de preparo (WhatsApp)<small>28/10 18:00 · entregue · lido</small></div></div><div class="at-row"><div class="grow">Resultado liberado, link com senha (WhatsApp)<small>14/10 16:12 · entregue</small></div></div><div class="at-row"><div class="grow">Pesquisa de satisfação<small>14/10 18:00 · respondida: nota 9</small></div></div></div>`
 :`<div class="steps"><div class="stp ok"><span class="dot2"></span><div class="st">Cadastro criado por Paula<small>12/03/2024 09:14 · Unidade 10</small></div></div><div class="stp ok"><span class="dot2"></span><div class="st">Telefone alterado por Rafael<small>02/08/2026 11:02 · (85) 98123-4455</small></div></div><div class="stp ok"><span class="dot2"></span><div class="st">Termo LGPD aceito na tela (versão 2)<small>14/10/2026 08:40</small></div></div><div class="stp cur"><span class="dot2"></span><div class="st">Ficha aberta por ${nomePerfil(PERFIL)}<small>hoje 09:00 · registrado na auditoria</small></div></div></div>`;
 openDrawer(esc(p.n),`<div class="tabs" role="tablist" style="flex-wrap:wrap">${abas.map(([k,t])=>`<button class="tab ${PC_ABA===k?'active':''}" onclick="pacFicha('${cpf}','${k}')">${t}</button>`).join('')}</div>${corpo}<div class="row"><button class="btn" onclick="closeDrawer();naNovo('atendimento','${cpf}',false,true)" ${tipAttr('Novo atendimento','Vai direto para os itens do pedido, com o paciente já preenchido (sem pedir o CPF de novo).')}>Novo atendimento</button><button class="btn sec" onclick="closeDrawer();clJornada({cpf:'${cpf}'})" ${tipAttr('Agendar jornada','Consulta, exames e ultrassom na mesma visita, com o preparo de tudo numa mensagem só.')}>Agendar jornada</button><button class="btn sec" onclick="pacEditar('${cpf}')" ${tipAttr('Editar','Abre a ficha para alterar; só os campos permitidos ao seu perfil ficam editáveis.')}>Editar</button><button class="btn ghost" onclick="modalOk('Desativar paciente?','<p>O cadastro de <b>${esc(p.n)}</b> deixa de abrir atendimento. Histórico e laudos continuam.</p><div class=\\'field\\'><label>Motivo <span class=\\'req\\'>*</span></label><select class=\\'in\\'><option>Pedido do paciente</option><option>Cadastro duplicado</option><option>Óbito</option></select></div>','Desativar','toast(\\'Paciente desativado, com motivo e registro\\',\\'warn\\')','danger')">Desativar</button></div>`)}
function pacNovo(){openModal(`${mh('Novo paciente')}<div class="mb"><div class="formgrid"><div class="field"><label>CPF <span class="req">*</span></label><input class="in" placeholder="000.000.000-00" oninput="this.value=mCPF(this.value)"></div><div class="field"><label>Nome completo <span class="req">*</span></label><input class="in"></div><div class="field"><label>Nascimento <span class="req">*</span></label><input class="in" type="date"></div><div class="field"><label>Sexo <span class="req">*</span></label><select class="in"><option>Feminino</option><option>Masculino</option></select></div><div class="field"><label>Nome da mãe ${info('Segunda identificação, usada na dupla checagem da coleta.')}</label><input class="in"></div><div class="field"><label>Telefone / WhatsApp <span class="req">*</span></label><input class="in" oninput="this.value=mTel(this.value)"></div></div><label class="check"><input type="checkbox" checked>Autoriza aviso de resultado por WhatsApp (termo versão 2)</label><div class="alert info"><span>CPF já cadastrado neste laboratório abre a ficha existente em vez de criar outra (evita duplicado).</span></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Paciente cadastrado!','Já dá para começar o atendimento pelo CPF.')">Cadastrar</button></div>`)}
function pacFundir(){openModal(`${mh('Fundir cadastros duplicados')}<div class="mb"><p style="font-size:14px">O sistema achou 2 cadastros parecidos. O que fica recebe todo o histórico do outro; nada é apagado.</p><div class="at-list"><label class="at-row check"><input type="radio" name="fd" checked><div class="grow">Maria Helena Souza · ***44477-** · 12/03/1961<small>5 atendimentos · fica</small></div></label><label class="at-row check"><input type="radio" name="fd"><div class="grow">Maria H. Souza · sem CPF · 12/03/1961<small>1 atendimento de 2023 · será fundido</small></div></label></div><div class="field"><label>Senha do gestor <span class="req">*</span></label><input class="in" type="password" placeholder="No protótipo, qualquer senha serve"></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Cadastros fundidos','O histórico ficou num cadastro só. A fusão está na auditoria, com quem fez e quando.')">Fundir</button></div>`)}
function pacImportar(){openModal(`${mh('Importar pacientes')}<div class="mb"><div class="field"><label>Origem</label><select class="in"><option>Banco do sistema antigo (conexão configurada)</option><option>Planilha no modelo do DeoClinic</option></select></div><div class="alert info"><span>Roda primeiro em testes e mostra o relatório: quantos entram, quantos ficam sem correspondência e quais duplicados precisam ser unificados. Pode repetir até a virada trazendo só o que mudou.</span></div><div class="mini">${miniKpi('Entram','18.402','')}${miniKpi('Sem correspondência','37','campo sexo vazio','warn')}${miniKpi('Duplicados','112','a unificar','warn')}</div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();toast('Importação em testes iniciada; o relatório chega por aviso')">Rodar em testes</button></div>`)}
GUIDES.pacientes=['Busque por nome, CPF ou telefone; a lista abre só com os ativos.','Clique na pessoa: a ficha abre na linha do tempo única (consultas, exames com gráfico, laudos de imagem, prescrições, pagamentos). Novo atendimento vai direto para os itens, com o paciente preenchido.','Importar e Exportar exigem permissão própria e ficam na auditoria; fundir duplicados pede a senha do gestor.'];
REGRAS['Pacientes']={aba:'Atendimento',itens:[['Cadastro','Um cadastro por CPF; sem CPF só com a exceção configurada. CPF aparece mascarado; o completo só para quem tem a permissão.'],['Crônicas','Respostas crônicas do questionário ficam no prontuário, com data e autor, e voltam preenchidas no próximo atendimento (D4).'],['Fusão','Fundir duplicados mantém todo o histórico e exige permissão própria; nada é apagado.'],['Importar e exportar','Exigem permissão própria; exportação sai com CPF mascarado; tudo fica na auditoria.'],['Desativar','Paciente desativado não abre atendimento; só o gestor reativa; histórico e laudos continuam.']]};

