/* Ficha do atendimento: situação dos exames por extenso (anotação 104) */
function atSituacaoLinhas(a){return String(a.tot||'').split(',').map(x=>{const m=x.trim().match(/^(\d+)\s*(\S+)$/);if(!m)return x.trim();const n=+m[1],k=m[2],pl=SIT_PLURAL[k]||k;return `<span class="at-letter" title="${LETRAS[k]||k}">${k}</span> ${n} ${n===1?'exame':'exames'} ${n===1?pl.replace(/s$/,''):pl}`}).join('<br>')}
/* Incluir exame num atendimento já feito (anotação 105): mesma busca do novo atendimento; paga a diferença; etiqueta nova se precisar de outro tubo. */
let AI={};
function atIncluirExame(prot){const a=ATENDS.find(x=>x.p===prot);if(!a)return;AI={prot,novos:[]};aiRender()}
function aiRender(){const a=ATENDS.find(x=>x.p===AI.prot);const am=AMOSTRAS.filter(x=>x.prot===AI.prot);const ja=[...new Set(am.flatMap(x=>x.ex))];const tot=AI.novos.reduce((s,c)=>s+EX[c].p,0);const tubos=[...new Set(AI.novos.map(c=>EX[c].m).filter(m=>m&&!am.some(x=>x.tipo===m)))];
 openModal(`${mh('Incluir exame · '+AI.prot)}<div class="mb"><p class="tl">${esc(a.n)} · ${LETRAS[a.sit]} · ${totTexto(a.tot)}. ${info('Dá para incluir enquanto o paciente ainda não saiu da coleta. Exame que usa um tubo já colhido aproveita a amostra; se precisar de outro tubo, sai etiqueta nova. Particular paga a diferença no caixa; convênio pede guia complementar.')}</p>
 ${ja.length?`<p style="font-size:13px;margin:6px 0"><b>Já no pedido:</b> ${ja.map(c=>`<span class="badge neutral" title="${EX[c]?EX[c].n:''}">${c}</span>`).join(' ')}</p>`:''}
 <div class="inwrap">${LUPA}<input class="in" id="aiQ" placeholder="Nome, código ou sinônimo do exame" autocomplete="off" oninput="$('#aiRes').innerHTML=aiResultados(this.value)" aria-label="Buscar exame"></div><div id="aiRes"></div>
 ${AI.novos.length?`<div class="at-list" style="margin-top:8px">${AI.novos.map((c,i)=>`<div class="at-row"><div class="grow">${EX[c].n}<small>${c} · ${EX[c].serv?'Serviço':EX[c].m}${EX[c].j?' · jejum de '+EX[c].j+' h':''}</small></div><span class="at-price">${fmt(EX[c].p)}</span><button class="ibtn plain" aria-label="Tirar" onclick="AI.novos.splice(${i},1);aiRender()">${I.x}</button></div>`).join('')}</div>
 <div class="at-totals"><div class="at-big"><span>Diferença a pagar</span><span>${fmt(tot)}</span></div></div>${tubos.length?`<div class="alert warn"><span>Precisa de outro tubo (${tubos.join(', ')}): sai etiqueta nova na sala de coleta.</span></div>`:'<div class="alert info"><span>Aproveita as amostras já colhidas: sem tubo novo.</span></div>'}`:'<div class="empty" style="padding:12px 8px"><h4>Nenhum exame novo ainda</h4><p>Busque acima para incluir.</p></div>'}
 </div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" ${AI.novos.length?'':'disabled'} onclick="aiSalvar()">Incluir ${AI.novos.length?AI.novos.length+(AI.novos.length>1?' exames':' exame'):''}</button></div>`,'wide');const q=$('#aiQ');if(q)q.focus()}
function aiResultados(q){q=semAc(q.trim());if(q.length<2)return '';const am=AMOSTRAS.filter(x=>x.prot===AI.prot);const ja=new Set([...am.flatMap(x=>x.ex),...AI.novos]);const r=EXAMES.filter(e=>!e.serv&&semAc(e.n+' '+e.c+' '+e.s).includes(q)).slice(0,6);
 if(!r.length)return '<p class="tl">Nada encontrado para essa busca.</p>';
 return `<div class="at-list">${r.map(e=>`<button class="at-row at-pick" ${ja.has(e.c)?'disabled':''} onclick="AI.novos.push('${e.c}');aiRender()"><div class="grow">${e.n}<small>${e.c} · ${e.m}${e.j?' · jejum de '+e.j+' h':''}</small></div><span class="at-price">${ja.has(e.c)?'já no pedido':fmt(e.p)}</span></button>`).join('')}</div>`}
function aiSalvar(){const a=ATENDS.find(x=>x.p===AI.prot);if(!a||!AI.novos.length)return;const n=AI.novos.length,tot=AI.novos.reduce((s,c)=>s+EX[c].p,0);
 /* soma os novos à etapa A (atendidos) no resumo e, se já houver tubos, cria a amostra nova */
 const partes=String(a.tot||'').split(',').map(x=>x.trim()).filter(Boolean);const i=partes.findIndex(x=>/ A$/.test(x));if(i>=0)partes[i]=(+partes[i].split(' ')[0]+n)+' A';else partes.push(n+' A');a.tot=partes.join(', ');
 const am=AMOSTRAS.filter(x=>x.prot===AI.prot);if(am.length){const b=am[0];AMOSTRAS.push({cod:AI.prot+'-'+String(am.length+1).padStart(2,'0')+'-01',prot:AI.prot,n:a.n,ex:[...AI.novos],tipo:EX[AI.novos[0]].m,banc:b.banc,sit:'A',urg:!!a.urg})}
 closeModal();retorno('ok',n+(n>1?' exames incluídos':' exame incluído'),`Diferença de ${fmt(tot)} registrada no caixa (${a.orig==='Clínicas'?'faturamento da rede':'particular'}). ${am.length?'Etiqueta nova enviada à sala de coleta.':'O paciente segue para a coleta com o pedido atualizado.'}`,[{l:'Abrir a ficha',on:`atFicha('${AI.prot}','exames')`},{l:'Fechar',sec:true}]);if(typeof reView==='function')reView()}
/* Cancelar atendimento (anotação 106): motivo obrigatório; cancela o que não foi colhido; estorno pela mesma forma. */
function atCancelar(prot){const a=ATENDS.find(x=>x.p===prot);if(!a)return;if(a.sit==='X'){toast('Este atendimento já está cancelado','warn');return}
 const colhido=!'A$'.includes(a.sit);
 openModal(`${mh('Cancelar atendimento '+prot+'?')}<div class="mb"><p><b>${esc(a.n)}</b> · ${LETRAS[a.sit]} · ${totTexto(a.tot)}.</p>
 <p style="font-size:14px;color:var(--fg2)">${colhido?'Já houve coleta: cancela só o que ainda não foi para a área técnica; o que já está lá continua e é cobrado. ':'Nada foi colhido ainda: cancela tudo. '}Estorno pela mesma forma de pagamento. Fica registrado com o seu nome, data e hora.</p>
 <div class="field"><label for="acMot">Motivo <span class="req">*</span></label><select class="in" id="acMot"><option value="">Escolha</option><option>Pedido do paciente</option><option>Erro de cadastro</option><option>Atendimento duplicado</option><option>Pedido médico inválido</option><option>Outro</option></select></div>
 <div class="field"><label for="acObs">Observação</label><input class="in" id="acObs" placeholder="Opcional"></div>
 </div><div class="mf"><button class="btn ghost" onclick="closeModal()">Voltar</button><button class="btn danger" onclick="atCancelarOk('${prot}')">Cancelar atendimento</button></div>`)}
function atCancelarOk(prot){const a=ATENDS.find(x=>x.p===prot);const mot=$('#acMot').value;if(!mot){toast('Escolha o motivo','warn');$('#acMot').focus();return}
 a.sit='X';a.cancel={mot,obs:$('#acObs').value,quem:'Você',q:dm(iso(HOJE))+' '+hhmm(new Date())};a.tot=String(a.tot||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>/ (A|\$|C)$/.test(x)?x.replace(/ \S+$/,' X'):x).join(', ');
 AMOSTRAS.forEach(x=>{if(x.prot===prot&&'AC'.includes(x.sit))x.sit='X'});
 closeModal();closeDrawer();if(typeof reView==='function')reView();retorno('ok','Atendimento '+prot+' cancelado','Motivo: '+mot+'. Estorno registrado pela mesma forma de pagamento. O cancelamento fica na auditoria com o seu nome.',[{l:'Entendi'}])}

