function clJPacs(){const q=semAc((CL_J.q||'').trim()),qd=soDig(CL_J.q||'');const l=PACIENTES.filter(p=>p.ativo&&(q.length<2||semAc(p.n).includes(q)||(qd.length>=3&&(soDig(p.cpf).includes(qd)||soDig(p.tel).includes(qd))))).slice(0,6);return l.length?`<div class="at-list">${l.map(p=>`<div class="at-row"><div class="grow">${esc(p.n)}<small>${cpfMask(p.cpf)} · ${dmy(p.dn)} · ${esc(p.tel)}</small></div><button class="btn sm sec" onclick="CL_J.pac='${esc(p.n)}';CL_J.passo=2;clJRender()">Escolher</button></div>`).join('')}</div>`:'<p class="tl">Ninguém com esse nome ou CPF. Faça o pré-cadastro abaixo.</p>'}
function clJPre(){const n=(($('#jPreN')||{}).value||'').trim(),t=soDig(($('#jPreT')||{}).value||'');if(!n||t.length<10){toast('Pré-cadastro: informe nome e telefone','warn');return}CL_J.pac=n;CL_J.passo=2;clJRender()}
function clJTog(c){const i=CL_J.itens.indexOf(c);if(i>=0)CL_J.itens.splice(i,1);else CL_J.itens.push(c);clJRender()}
function clJExames(q){q=semAc(q.trim());if(q.length<2)return '';const r=EXAMES.filter(e=>!e.serv&&semAc(e.n+' '+e.c+' '+e.s).includes(q)).slice(0,6);return r.length?`<div class="cl-jpick" style="margin-top:6px">${r.map(e=>`<button type="button" class="chip ${CL_J.itens.includes(e.c)?'on':''}" onclick="clJTog('${e.c}')">${esc(e.n)} · ${fmt(e.p)}</button>`).join('')}</div>`:'<p class="tl">Nada encontrado.</p>'}
/* Ordem: coleta (jejum) → imagem (bexiga cheia antes de vazia) → procedimentos → consulta por último, com os resultados do dia */
function clJSequencia(){const J=CL_J,lab=J.itens.filter(c=>EX[c]&&!EX[c].proc),img=J.itens.filter(c=>PROC(c)&&PROC(c).tipo==='Imagem').sort((a,b)=>(/cheia/i.test(PROC(b).prep||'')?1:0)-(/cheia/i.test(PROC(a).prep||'')?1:0)),prc=J.itens.filter(c=>PROC(c)&&PROC(c).tipo==='Procedimento'),con=J.itens.filter(c=>PROC(c)&&PROC(c).tipo==='Consulta');
 let [hh,mm]=(J.h||'07:40').split(':').map(Number);let t=hh*60+(mm||0);const hs=()=>String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');const out=[];
 if(lab.length){const dom=lab.includes('DOM');out.push({h:hs(),itens:lab,sala:dom?'dom':'s5',prof:'',dur:10,tipo:dom?'Domiciliar':'Coleta',motivo:lab.some(c=>EX[c].j)?'primeiro, por causa do jejum':''});t+=dom?60:20}
 img.forEach(c=>{const p=PROC(c);out.push({h:hs(),itens:[c],sala:'s3',prof:'p2',dur:p.dur,tipo:'Imagem',motivo:/jejum/i.test(p.prep||'')?'ainda em jejum':''});t+=p.dur});
 prc.forEach(c=>{const p=PROC(c);out.push({h:hs(),itens:[c],sala:c==='30101921'?'s7':'s4',prof:c==='40101010'?'p4':c==='30101921'?'p3':'p6',dur:p.dur,tipo:'Procedimento'});t+=p.dur});
 con.forEach(c=>{const p=PROC(c);if(out.length)t+=10;out.push({h:hs(),itens:[c],sala:J.prof==='p1'?'s1':'s2',prof:J.prof,dur:p.dur,tipo:'Consulta',motivo:out.length?'por último, depois do café':''});t+=p.dur});
 return out}
function clJConfirmar(){const J=CL_J,seq=clJSequencia(),id='J-0'+(CL_JSEQ++);seq.forEach(s=>CL_AG_NOVOS.push({h:s.h,pac:J.pac,itens:s.itens,prof:s.prof,sala:s.sala,tipo:s.tipo,sit:'agendado',conv:'Particular',pago:false,jornada:id,dia:J.dia}));
 if(J.pre&&!PACIENTES.some(p=>p.n===J.pac))toast('Pré-cadastro criado: CPF e dados completam na chegada');closeModal();if(location.hash==='#agenda')reView();
 retorno('ok','Jornada '+id+' marcada!',`${J.pac.split(' ')[0]} tem ${seq.length} ${seq.length>1?'etapas':'etapa'} ${J.dia==='hoje'?'hoje':'em '+J.dia}, a partir das ${seq[0].h}. O preparo foi por WhatsApp e o lembrete sai na véspera às 18h.`,[{l:'Ver na agenda',on:"AG_MODO='grade';location.hash='#agenda'"},{l:'Fechar',sec:true}])}
GUIDES.agenda=['A agenda de hoje junta consultas, ultrassom, procedimentos, coleta do laboratório e domiciliar. Veja por profissional ou por sala e filtre por tipo.','Clique no paciente para ver o preparo de cada item, confirmar a chegada, receber, remarcar ou registrar falta.','Marcar abre a jornada: escolha consulta, exames e ultrassom; o sistema monta a ordem (jejum primeiro, consulta por último) e a mensagem de preparo.','A semana da coleta (laboratório) continua num modo próprio, com coleta geral, infantil e domiciliar por janelas.'];
